B.arP=s(["\u8a18\u5e33\u652f\u63f4\u53f0\u5e63\u3001\u7f8e\u5143\u3001\u65e5\u5713\u7b49\u5e63\u5225\uff0c\u5404\u5e63\u5225\u5206\u958b\u7d71\u8a08\u4e26\u907f\u514d\u6df7\u5408\u8a08\u7b97\u3002","\u5c0f\u55b5\u624b\u624b\u52d5\u65b0\u589e\u6539\u70ba\u9010\u984c\u586b\u5beb\uff0c\u53ef\u9078\u64c7\u624b\u586b\u6216\u9010\u6b65\u8a9e\u97f3\u8f38\u5165\u3002","\u9996\u6b21\u767b\u5165\u5148\u8f09\u5165\u9996\u9801\u8207\u5c0f\u55b5\u624b\u5716\u7247\uff0c\u5176\u4ed6\u9801\u9762\u5716\u7247\u5728\u80cc\u666f\u88dc\u8f09\uff1bPC \u53ef\u4f7f\u7528 Tab \u8207 Enter \u5feb\u901f\u8f38\u5165\u3002"],t.s)
B.al0=s(["Ledger entries support TWD, USD, JPY, and other currencies with separate totals to avoid mixed-currency calculations.","Manual helper entry now guides typed or voice input one field at a time.","The first signed-in view loads dashboard and helper artwork first; remaining artwork loads in the background, with Tab and Enter support on desktop."],t.s)
B.U8=new A.dV("v1.2.97+105","\u65b0\u589e\u591a\u5e63\u5225\u8a18\u5e33\u8207\u9010\u984c\u65b0\u589e","Multi-currency ledger and step-by-step entry",B.arP,B.al0)
B.akY=s(["\u9031\u671f\u9805\u76ee\u7ba1\u7406\u65b0\u589e\u7d05\u8272\u300c\u522a\u9664\u9031\u671f\u300d\u6309\u9215\u8207\u78ba\u8a8d\u8996\u7a97\u3002","\u522a\u9664\u6703\u505c\u6b62\u5f8c\u7e8c\u81ea\u52d5\u5efa\u7acb\uff0c\u4e26\u79fb\u9664\u660e\u5929\u8d77\u9810\u5148\u5efa\u7acb\u7684\u8cc7\u6599\u3002","\u4eca\u5929\u8207\u4ee5\u524d\u7684\u8a18\u5e33\u3001\u884c\u7a0b\u8207\u4efb\u52d9\u6703\u4fdd\u7559\uff0c\u4e0d\u6703\u56e0\u522a\u9664\u9031\u671f\u8a2d\u5b9a\u800c\u6d88\u5931\u3002"],t.s)
B.apn=s(["Recurring item management now includes a red Delete recurrence action with confirmation.","Deletion stops future generation and removes pre-created items from tomorrow onward.","Ledger entries, schedules, and tasks from today and earlier remain available."],t.s)
B.U3=new A.dV("v1.2.96+104","\u65b0\u589e\u9031\u671f\u9805\u76ee\u522a\u9664","Added recurring-item deletion",B.akY,B.apn)
B.arJ=s(["\u6709\u622a\u6b62\u65e5\u7684\u9031\u671f\u9805\u76ee\u6703\u5728\u622a\u6b62\u65e5\u9694\u5929\u81ea\u52d5\u5f9e\u7ba1\u7406\u6e05\u55ae\u79fb\u9664\uff0c\u5df2\u5efa\u7acb\u7684\u8cc7\u6599\u4ecd\u6703\u4fdd\u7559\u3002","\u7121\u9650\u9031\u671f\u4e2d\u6b62\u5f8c\u6703\u4fdd\u7559\u5230\u6700\u5f8c\u751f\u6210\u65e5\u671f\uff0c\u4e26\u5728\u9694\u5929\u81ea\u52d5\u6e05\u9664\uff1b\u555f\u7528\u4e2d\u7684\u7121\u9650\u9031\u671f\u4e0d\u53d7\u5f71\u97ff\u3002","\u624b\u52d5\u8207\u5c0f\u55b5\u624b\u65b0\u589e\u6642\uff0c\u4fe1\u7528\u5361\u3001\u8cb8\u6b3e\u3001\u501f\u8cb8\u8207\u96fb\u4fe1\u4ee3\u4ed8\u7b49\u4ed8\u6b3e\u65b9\u5f0f\u6703\u81ea\u52d5\u5206\u985e\u70ba\u9810\u4ed8\u652f\u51fa\uff0c\u5be6\u969b\u9084\u6b3e\u4ecd\u70ba\u4e00\u822c\u652f\u51fa\u3002"],t.s)
B.aoc=s(["Finite recurring rules are removed from management the day after their end date while generated records remain available.","Paused unlimited rules remain through their final generated date and are removed the next day; active unlimited rules remain unchanged.","Manual and helper-created entries using credit cards, loans, borrowing, or carrier billing are classified as advance expenses while repayments remain regular expenses."],t.s)
B.Uh=new A.dV("v1.2.95+103","\u9031\u671f\u6e05\u7406\u8207\u9810\u4ed8\u652f\u51fa\u81ea\u52d5\u5206\u985e","Recurring-item cleanup and automatic advance-expense classification",B.arJ,B.aoc)
B.aat=s(["\u8a18\u5e33\u3001\u884c\u7a0b\u8207\u5de5\u4f5c\u4efb\u52d9\u53ef\u8a2d\u5b9a\u6bcf\u65e5\u3001\u6bcf 2 \u81f3 10 \u5929\u6216\u6bcf\u6708\u6307\u5b9a\u65e5\u671f\u91cd\u8907\u3002","\u53ef\u8a2d\u5b9a\u622a\u6b62\u65e5\u671f\u6216\u7121\u9650\u671f\u57f7\u884c\uff0c\u4e26\u80fd\u5f9e\u9031\u671f\u9805\u76ee\u7ba1\u7406\u4e2d\u505c\u6b62\u6216\u6062\u5fa9\u3002","\u6bcf\u6708 15 \u65e5\u8d77\u6703\u9810\u5148\u5efa\u7acb\u4e0b\u500b\u6708\u8cc7\u6599\uff0c\u522a\u9664\u55ae\u6b21\u7d00\u9304\u5f8c\u4e0d\u6703\u518d\u6b21\u81ea\u52d5\u88dc\u56de\u3002"],t.s)
B.adq=s(["Ledger entries, schedules, and work tasks can repeat daily, every 2 to 10 days, or on a selected monthly date.","Recurring items support an optional end date or no end date and can be paused or resumed from the account menu.","The next month is prepared from the 15th, while deleted individual occurrences stay excluded."],t.s)
B.Ug=new A.dV("v1.2.94+102","\u65b0\u589e\u9031\u671f\u5e33\u52d9\u3001\u884c\u7a0b\u8207\u4efb\u52d9","Recurring ledger, schedule, and task items",B.aat,B.adq)
B.acd=s(["\u8aaa\u8a71\u6ce1\u6ce1\u6703\u4f9d\u6587\u5b57\u9577\u77ed\u81ea\u52d5\u8abf\u6574\u5bec\u5ea6\uff0c\u6587\u5b57\u3001\u6ce1\u6ce1\u8207\u7bad\u982d\u6703\u4fdd\u6301\u8cbc\u8fd1\u5c0f\u55b5\u624b\u3002","\u5f85\u6a5f\u53f0\u8a5e\u6539\u70ba\u8ddf\u96a8\u52d5\u756b\u5207\u63db\u89f8\u767c\uff0c\u6bcf\u8f2a\u96a8\u6a5f\u986f\u793a\u96f6\u5230\u5169\u6b21\uff0c\u9023\u7e8c\u5169\u6b21\u5f8c\u6703\u5b89\u975c\u4e00\u8f2a\u3002","\u8214\u6bdb\u3001\u6293\u7662\u8207\u8eba\u8457\u73a9\u52a0\u5165\u5c08\u5c6c\u53f0\u8a5e\uff0c\u4e26\u589e\u52a0\u66f4\u591a\u8a18\u9304\u63d0\u9192\u8207\u9017\u8da3\u6587\u53e5\u3002"],t.s)
B.ajW=s(["Idle speech bubbles now size themselves to the message while keeping the text and tail beside the helper.","Idle prompts now follow animation changes, appear zero to two times per sequence, and pause after two consecutive prompts.","Grooming, scratching, and playful animations now have matching phrases alongside more helpful and playful messages."],t.s)
B.Ud=new A.dV("v1.2.91+99","\u6539\u5584\u5c0f\u55b5\u624b\u6ce1\u6ce1\u8207\u5f85\u6a5f\u4e92\u52d5","Improved Mew helper bubbles and idle interactions",B.acd,B.ajW)
B.aiD=s(["\u672c\u6708\u9810\u4ed8\u652f\u51fa\u6539\u70ba\u986f\u793a\u672c\u6708\u5df2\u652f\u4ed8\u91d1\u984d\u8207\u622a\u81f3\u672c\u6708\u7684\u61c9\u4ed8\u7e3d\u984d\uff0c\u8de8\u6708\u4efd\u7d50\u8f49\u66f4\u76f4\u89ba\u3002","\u55ae\u7b46\u9810\u4ed8\u652f\u51fa\u6539\u70ba\u5df2\u652f\u4ed8\uff0f\u61c9\u4ed8\u7e3d\u984d\uff0c\u6536\u5408\u72c0\u614b\u65b0\u589e\u65e5\u671f\u8207\u5b8c\u6574\u9032\u5ea6\u689d\u3002","\u79fb\u9664\u96fb\u8166\u7248\u9802\u5217\u91cd\u8907\u7684\u8a9e\u8a00\u5207\u63db\u6309\u9215\uff0c\u8a9e\u8a00\u8a2d\u5b9a\u7d71\u4e00\u653e\u5728\u5e33\u865f\u9078\u55ae\u3002"],t.s)
B.ahu=s(["The monthly advance-expense summary now shows paid this month versus the total due through the selected month.","Each advance expense now shows paid versus due, with its date and a full-width progress bar in the collapsed card.","Removed the duplicate desktop language switcher and kept language settings in the account menu."],t.s)
B.Um=new A.dV("v1.2.90+98","\u8abf\u6574\u9810\u4ed8\u652f\u51fa\u7d71\u8a08\u8207\u8cc7\u8a0a\u5361","Improved advance-expense summaries and cards",B.aiD,B.ahu)
